void main() {
  vec2 g = uv * 8.0;
  vec2 cell = floor(g);
  vec2 f = abs(fract(g) - 0.5);
  float pane = (1.0 - smoothstep(0.24, 0.28, f.x)) * (1.0 - smoothstep(0.28, 0.32, f.y));
  float lit = step(0.68, hash(cell + floor(print_time() * 0.4 + hash(cell) * 4.0) * 13.0));
  gl_FragColor = vec4(pane, pane * lit, 0.0, 1.0);
}

void main() {
  float y = min(uv.y, 2.0 * horizon - uv.y);
  float sky = 0.55 * pow(clamp(y / horizon, 0.0, 1.0), 2.2);
  float cloud = smoothstep(0.6, 0.8, noise(vec2(uv.x * 2.5 - print_time() * 0.05, y * 7.0)));
  float tone = (sky + 0.3 * cloud * (1.0 - smoothstep(0.3, 0.6, y / horizon))) * mix(1.0, 0.55, step(horizon, uv.y));
  gl_FragColor = vec4(vec3(tone * (1.0 - step(0.5, skyline(uv).x))), 1.0);
}

float birds(vec2 p) {
  float t = print_time();
  float ink = 0.0;
  for (int i = 0; i < 3; i++) {
    float k = float(i);
    vec2 q = p - vec2(fract(t * 0.03 + k * 0.37) * 1.6 - 0.1, 0.1 + 0.07 * k + 0.01 * sin(t * 2.0 + k * 2.0));
    q.x = abs(q.x);
    float flap = mod(floor(t * 4.0 + k), 2.0) * 1.2 - 0.6;
    ink = max(ink, (1.0 - smoothstep(0.003, 0.006, abs(q.y + q.x * flap))) * (1.0 - smoothstep(0.016, 0.02, q.x)));
  }
  return ink;
}

void main() {
  vec2 at = uv;
  float water = step(horizon, uv.y);
  float stroke = 1.0;
  if (water > 0.5) {
    float wave = noise(vec2(uv.x * 3.0, uv.y * 80.0 + print_time() * 2.0));
    at = vec2(uv.x + (wave - 0.5) * 0.05, 2.0 * horizon - uv.y);
    stroke = step(0.35 + 0.5 * (uv.y - horizon) / (1.0 - horizon), noise(vec2(uv.x * 10.0 + wave * 4.0, uv.y * 120.0)));
  }
  vec3 city = skyline(at);
  vec2 w = vec2(0.0);
  if (gl_FragCoord.x >= 0.0) w = texture2D(iChannel0, 1.0 - abs(1.0 - mod(city.yz, 2.0))).rg;
  float near = step(1.5, city.x);
  float tone = step(0.5, city.x) * mix(0.5, 1.0 - 0.5 * w.r, near) * (1.0 - w.g) * mix(1.0, near, water);
  tone = max(tone * stroke, birds(vec2(uv.x * iResolution.x / iResolution.y, uv.y)));
  gl_FragColor = vec4(vec3(tone), 1.0);
}

void main() {
  vec2 at = uv;
  float water = step(horizon, uv.y);
  float stroke = 1.0;
  if (water > 0.5) {
    float wave = noise(vec2(uv.x * 3.0, uv.y * 80.0 + print_time() * 2.0));
    at = vec2(uv.x + (wave - 0.5) * 0.05, 2.0 * horizon - uv.y);
    stroke = step(0.35 + 0.5 * (uv.y - horizon) / (1.0 - horizon), noise(vec2(uv.x * 10.0 + wave * 4.0, uv.y * 120.0)));
  }
  float aspect = iResolution.x / iResolution.y;
  float moon = 1.0 - smoothstep(0.1, 0.105, length((at - vec2(0.7, 0.24)) * vec2(aspect, 1.0)));
  vec3 city = skyline(at);
  float lit = 0.0;
  if (gl_FragCoord.x >= 0.0) lit = texture2D(iChannel0, 1.0 - abs(1.0 - mod(city.yz, 2.0))).g;
  gl_FragColor = vec4(vec3(mix(moon, lit, step(0.5, city.x)) * stroke), 1.0);
}

void main() {
  vec3 col = texture2D(iChannel0, uv).rgb;
  vec2 p = floor(uv * iResolution.xy);
  float fibre = smoothstep(0.55, 0.9, noise(vec2(uv.x * 380.0 + uv.y * 90.0, uv.y * 30.0 - uv.x * 14.0)));
  fibre += smoothstep(0.6, 0.9, noise(vec2(uv.x * 26.0 - uv.y * 40.0, uv.y * 300.0 + uv.x * 70.0)));
  float speck = smoothstep(0.93, 1.0, hash(p + floor(print_time() * rate) * 31.0));
  col = mix(col, paper, speck * amount);
  gl_FragColor = vec4(col * (1.0 - 0.1 * amount * fibre), 1.0);
}
